joi_block.script:
phase := 0
if (phase == 0) {
wait until((#ServerRack).airQualitySensor_humidity > 70)
    phase = 1
    (#Dehumidifier #Lab).dehumidifier_setDehumidifierMode("dehumidifying")
}
else {
h = (#ServerRack).airQualitySensor_humidity
    if (h < 50) {
(#Dehumidifier #Lab).switch_off()
}
}

n := 0
if (n % 2 == 0) {
all(#Valve).valve_open()
}
else {
all(#Valve).valve_close()
}
n = n + 1

n := 0
if (n % 2 == 0) {
all(#Window).windowCovering_upOrOpen()
}
else {
all(#Window).windowCovering_downOrClose()
}
n = n + 1

triggered := false
if ((#Hallway #MultiButton).multiButton_button1 == "pushed") {
if (triggered == false) {
tmp = (#Hallway #Light).light_currentBrightness + 10
        if (tmp > 100) {
tmp = 100
}
(#Hallway #Light).light_moveToBrightness(tmp, 0.0)
        triggered = true
}
}
else {
triggered = false
}

triggered := false
if ((#Hallway #MultiButton).multiButton_button2 == "pushed") {
if (triggered == false) {
tmp = (#Hallway #Light).light_currentBrightness - 10
        if (tmp < 0) {
tmp = 0
}
(#Hallway #Light).light_moveToBrightness(tmp, 0.0)
        triggered = true
}
}
else {
triggered = false
}

n := 0
triggered := false
if ((#LivingRoom #MultiButton).multiButton_button4 == "pushed") {
if (triggered == false) {
if (n % 3 == 0) {
all(#Light #LivingRoom).light_moveToBrightness(25.0, 0.0)
}
else {
if (n % 3 == 1) {
all(#Light #LivingRoom).light_moveToBrightness(50.0, 0.0)
}
else {
all(#Light #LivingRoom).light_moveToBrightness(75.0, 0.0)
}
}
triggered = true
}
}
else {
triggered = false
}
n = n + 1

triggered := false
if ((#Bedroom #MultiButton).multiButton_button3 == "pushed") {
if (triggered == false) {
tmp = (#Bedroom #LevelControl).light_currentBrightness + 5
        if (tmp > 80) {
tmp = 80
}
(#Bedroom #LevelControl).light_moveToBrightness(tmp, 0.0)
        triggered = true
}
}
else {
triggered = false
}

triggered := false
if ((#LivingRoom #MultiButton).multiButton_button4 == "pushed") {
if (triggered == false) {
tmp = (#LevelControl #LivingRoom).levelControl_currentLevel - 15
        if (tmp < 10) {
tmp = 10
}
(#LevelControl #LivingRoom).levelControl_moveToLevel(tmp, 0.0)
        triggered = true
}
}
else {
triggered = false
}

temp = any(#TemperatureSensor).temperatureSensor_temperature
if (temp >= 20 and temp < 30) {
all(#AirConditioner).airConditioner_setAirConditionerMode("auto")
}
else {
if (temp >= 30) {
all(#AirConditioner).airConditioner_setAirConditionerMode("cool")
}
}

hold_ticks := 0
if ((#Printer).charger_power < 5) {
hold_ticks = hold_ticks + 1
    if (hold_ticks >= 600) {
(#Printer).switch_off()
        break
}
}
else {
hold_ticks = 0
}

hold_ticks := 0
if ((#TV).charger_power < 10) {
hold_ticks = hold_ticks + 1
    if (hold_ticks >= 900) {
(#TV).switch_off()
        break
}
}
else {
hold_ticks = 0
}

hold_ticks := 0
if ((#Charger).charger_power < 5) {
hold_ticks = hold_ticks + 1
    if (hold_ticks >= 1800) {
(#Charger).switch_off()
        break
}
}
else {
hold_ticks = 0
}
